import{_ as a,o as i,c as t,ao as r}from"./chunks/framework.oFTNvpj4.js";const u=JSON.parse('{"title":"WaterLily.jl","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":null}'),o={name:"about.md"};function n(s,e,l,d,p,c){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="WaterLily.jl" tabindex="-1">WaterLily.jl <a class="header-anchor" href="#WaterLily.jl" aria-label="Permalink to &quot;WaterLily.jl {#WaterLily.jl}&quot;">​</a></h1><p>WaterLily is a simple and fast fluid simulator written in pure <a href="https://julialang.org/" target="_blank" rel="noreferrer">Julia</a>. It solves the unsteady incompressible Navier-Stokes equations on a Cartesian grid, immerses solid boundaries using the Boundary Data Immersion Method, and runs on serial CPU, multi-threaded CPU, and GPU backends. The aim is to be i) simple to read and extend, ii) fast, and iii) backend-agnostic.</p><h2 id="Capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#Capabilities" aria-label="Permalink to &quot;Capabilities {#Capabilities}&quot;">​</a></h2><ul><li><p>Incompressible viscous flow in two and three dimensions, around bodies that can move and deform. A body is defined by a signed distance function and an optional coordinate map, so there is no mesh to generate or update (<a href="./reference/bodies">bodies and geometry</a>).</p></li><li><p>Composite geometries built from simpler ones with set operations, and forces and moments measured on the whole body or on any part of it (<a href="./reference/metrics">flow metrics</a>).</p></li><li><p>Uniform, space- and time-varying inflow, periodic directions, a convective exit, and a body force through the domain acceleration <code>g(i,x,t)</code> (<a href="./reference/simulation">simulation</a>).</p></li><li><p>The same source runs serially, multi-threaded, or on a GPU, by passing for example <code>mem=CuArray</code> (NVIDIA) or <code>mem=ROCArray</code> (AMD) (<a href="./reference/grid">grid, loops and boundary conditions</a>).</p></li><li><p>The solver is differentiable: it runs on ForwardDiff dual numbers, so a simulation can be differentiated with respect to its parameters.</p></li><li><p>Time averaging, sub-grid-scale modelling, VTK output for ParaView, JLD2 restarts, and plotting with Plots or Makie (<a href="./reference/io">input and output</a>, <a href="./reference/plotting">plotting</a>, <a href="./reference/utilities">utilities</a>).</p></li></ul>',4)])])}const f=a(o,[["render",n]]);export{u as __pageData,f as default};
